import{_ as i,l as n,o as e,c as s,v as r,p as l,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"VPN 对零信任","description":"","frontmatter":{"title":"VPN 对零信任","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vpn-zero-trust.md","filePath":"cs/vpn-zero-trust.md","lastUpdated":1789023840000}'),c={name:"cs/vpn-zero-trust.md"};function E(A,a,u,P,_,m){const o=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="vpn-对零信任" tabindex="-1">VPN 对零信任 <a class="header-anchor" href="#vpn-对零信任" aria-label="Permalink to &quot;VPN 对零信任&quot;">​</a></h1><div class="epigraph"><p>VPN 把远程主机变成「已在内网」；零信任把每次请求当成来自敌意网络。二者不是口号替换，是信任锚从网段迁到身份、设备与请求上下文。</p><footer>—— 据 Kindervag 的零信任陈述；NIST SP 800-207；对照 Anderson 对边界模型</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/wireguard">WireGuard</a>仍是一条（漂亮的）隧道。缺口是<strong>边界模型本身</strong>：进了隧道就侧向移动。本课对照，不把零信任架构的整本 SP 提前写完（那在治理课序）。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IPsec/WG 成功后，用户拥有网段级路由。横向用<a href="/cs/arp-spoofing">ARP</a>或扫描内网服务。零信任：认证+设备姿态+最小授权到应用，网络层加密仍可有，但不等于授权。缺口是信任迁移，不是再配一条隧道。</p><h3 id="加密不等于授权" tabindex="-1">加密不等于授权 <a class="header-anchor" href="#加密不等于授权" aria-label="Permalink to &quot;加密不等于授权&quot;">​</a></h3><p>mTLS 与隧道都加密。授权是「这个主体对这个资源的这个动作」。</p><p><span class="marginnote">NIST SP 800-207。BeyondCorp 是公开工程叙述。本课不写打穿某企业 VPN 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列 VPN 假设：私网、粗粒度 ACL。列零信任假设：身份提供者、短命凭证、每请求验。指出混合：隧道仍用于合规或遗留协议，应用仍要鉴权。</p>',12)),(e(),l(h,null,{default:t(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20VPN%5B%22%E8%BF%9B%E9%9A%A7%E9%81%93%20%3D%20%E5%86%85%E7%BD%91%22%5D%20--%3E%20LAT%5B%22%E4%BE%A7%E5%90%91%E9%9D%A2%E5%A4%A7%22%5D%0A%20%20ZT%5B%22%E6%AF%8F%E8%AF%B7%E6%B1%82%E8%BA%AB%E4%BB%BD%E4%B8%8E%E5%A7%BF%E6%80%81%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E6%8E%88%E6%9D%83%22%5D%0A%20%20TUN%5B%22%E4%BB%8D%E5%8F%AF%E5%8A%A0%E5%AF%86%E4%BC%A0%E8%BE%93%22%5D%20--%3E%20ZT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信道单元要结束「链路保密」并开始「谁在链上」。Wi-Fi 下一课是最后一跳的链路层合同，同样不能代替应用身份。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开策略引擎产品。WPA2/WPA3 下一课：无线链路的认证与前向。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隧道解决路径保密与粗准入，不解决横向。</li><li>零信任把锚放到身份与请求。</li><li>二者可叠加：加密传输 + 每请求授权。</li><li>下一课 WPA2/WPA3。</li><li>出处：NIST SP 800-207；Kindervag；Anderson, <em>Security Engineering</em>。</li></ul>',8))])}const T=i(c,[["render",E]]);export{f as __pageData,T as default};
